/* Tone curves of the front side: up to 6 points per colour from settings (0x109.., 0x11B..)
   or the defaults, fitted into img_tone_curves[0][colour][1024]. */
void img_build_tone_curves_front(void)
{
    unsigned int count, j, tone_x, i;
    unsigned int points[20];
    for (i = 0; i < 3; i++) {
        if (img_tone_points_unset(0) != 0) {
            for (count = 0; count < 6; count++) {
                points[(count + 1) * 2] = img_default_tone_x_front[count * 2];
                (&points[(count + 1) * 2])[1] = img_default_tone_x_front[count * 2] - img_default_tone_y_front[count * 2];
            }
        } else {
            for (j = 0, count = 0; j < 6; j++, count++) {
                tone_x = settings[0x109 + i * 6 + j];
                if (!tone_x) {
                    count = count - 1;
                    continue;
                }
                points[(count + 1) * 2] = tone_x;
                (&points[(count + 1) * 2])[1] = tone_x - settings[0x11b + i * 6 + j];
            }
        }
        points[0] = 0;
        points[1] = 0;
        points[(count + 1) * 2] = 0xff;
        (&points[(count + 1) * 2])[1] = 0;
        img_fit_tone_curve(points + 2, count, 0, i);
        img_fit_tone_curve_ends(points, count + 2, 0, i);
    }
    util_mem_copy(img_tone_x_built, &settings[0x109], 0x12);
    util_mem_copy(img_tone_front_built, settings_tone_front_0, 0x12);
}

void img_build_tone_curves_back(void)
{
    unsigned int count, j, tone_x, i;
    unsigned int points[20];
    for (i = 0; i < 3; i++) {
        if (img_tone_points_unset(1) != 0) {
            for (count = 0; count < 6; count++) {
                points[(count + 1) * 2] = img_default_tone_x_back[count * 2];
                (&points[(count + 1) * 2])[1] = img_default_tone_x_back[count * 2] - img_default_tone_y_back[count * 2];
            }
        } else {
            for (j = 0, count = 0; j < 6; j++, count++) {
                tone_x = settings[0x109 + i * 6 + j];
                if (!tone_x) {
                    count = count - 1;
                    continue;
                }
                points[(count + 1) * 2] = tone_x;
                (&points[(count + 1) * 2])[1] = tone_x - settings[0x12d + i * 6 + j];
            }
        }
        points[0] = 0;
        points[1] = 0;
        points[(count + 1) * 2] = 0xff;
        (&points[(count + 1) * 2])[1] = 0;
        img_fit_tone_curve(points + 2, count, 1, i);
        img_fit_tone_curve_ends(points, count + 2, 1, i);
    }
    util_mem_copy(img_tone_x_built, &settings[0x109], 0x12);
    util_mem_copy(img_tone_back_built, settings_tone_back_0, 0x12);
}

int img_tone_points_unset(int side)
{
    char buf[4];
    if (side == 1) {
        if (util_mem_all_equal(&settings[0x109], 0, 6, buf) || util_mem_all_equal(settings_tone_x_1, 0, 6, buf) || util_mem_all_equal(settings_tone_x_2, 0, 6, buf) || util_mem_all_equal(settings_tone_back_0, 0, 6, buf) || util_mem_all_equal(settings_tone_back_1, 0, 6, buf) || util_mem_all_equal(settings_tone_back_2, 0, 6, buf)) {
            return 1;
        }
    } else {
        if (util_mem_all_equal(&settings[0x109], 0, 6, buf) || util_mem_all_equal(settings_tone_x_1, 0, 6, buf) || util_mem_all_equal(settings_tone_x_2, 0, 6, buf) || util_mem_all_equal(settings_tone_front_0, 0, 6, buf) || util_mem_all_equal(settings_tone_front_1, 0, 6, buf) || util_mem_all_equal(settings_tone_front_2, 0, 6, buf)) {
            return 1;
        }
    }
    return 0;
}

/* Fits points {x, y} (0..255) into a 1024-entry curve: cubic spline (img_spline_prepare/img_spline_eval) for
   more than two points, a straight line for two; values clamped to -128..127. */
void img_fit_tone_curve(struct img_spline_point *in_points, int count, int side, int colour)
{
    struct img_spline_point points[10];
    int swap_y, swap_x, i, j;
    double slope, intercept;
    double moments[10];
    short value;
    if (count > 10 || count < 2) return;
    for (i = 0; i < count; i++) {
        if (count == 2) points[i].x = in_points[i].x * 4;
        else points[i].x = in_points[i].x * 4 + 3;
        if ((settings_byte_0x70[0] & 4) == 0) points[i].y = in_points[i].y * 4;
        else points[i].y = in_points[i].y;
    }
    i = 0;
    while (i < count - 1) {
        if (points[i].x > points[i + 1].x) {
            swap_x = points[i].x;
            swap_y = points[i].y;
            points[i].x = points[i + 1].x;
            points[i].y = points[i + 1].y;
            points[i + 1].x = swap_x;
            points[i + 1].y = swap_y;
            i = 0;
        } else if (points[i].x == points[i + 1].x) {
            for (j = i + 1; j < count - 1; j++) {
                points[j].x = points[j + 1].x;
                points[j].y = points[j + 1].y;
            }
            count--;
        } else {
            i++;
        }
    }
    util_mem_clear(img_tone_curves[side][colour], 0x400);
    if (count > 2) {
        img_spline_prepare(points, count, moments);
        for (j = 0; j < 0x400; j++) {
            if (j <= points[0].x) value = points[0].y;
            else if (j >= points[count - 1].x) value = points[count - 1].y;
            else value = img_spline_eval(j, points, count, moments);
            if (value > 127) value = 127;
            else if (value < -128) value = -128;
            img_tone_curves[side][colour][j] = value;
        }
    } else {
        slope = ((double)points[1].y - points[0].y) / ((double)points[1].x - points[0].x);
        intercept = (double)points[0].y - points[0].x * slope;
        for (i = 0; i < 0x400; i += 4) {
            value = i * slope + intercept;
            if (value > 127) value = 127;
            else if (value < -128) value = -128;
            img_tone_curves[side][colour][i] = value;
            img_tone_curves[side][colour][i + 1] = value;
            img_tone_curves[side][colour][i + 2] = value;
            img_tone_curves[side][colour][i + 3] = value;
        }
    }
}

int img_tone_curve_in_use(int side)
{
    int unused_frame;
    if ((settings_test_flags[0] & 8) || !win_params.flags.f.adf) {
        return 0;
    }
    if (img_tone_curves[side][0][0] != 0 || img_tone_curves[side][0][0xff] != 0 || img_tone_curves[side][0][0x1ff] != 0 || img_tone_curves[side][0][0x2ff] != 0 || img_tone_curves[side][0][0x3ff] != 0
        || img_tone_curves[side][1][0] != 0 || img_tone_curves[side][1][0xff] != 0 || img_tone_curves[side][1][0x1ff] != 0 || img_tone_curves[side][1][0x2ff] != 0 || img_tone_curves[side][1][0x3ff] != 0
        || img_tone_curves[side][2][0] != 0 || img_tone_curves[side][2][0xff] != 0 || img_tone_curves[side][2][0x1ff] != 0 || img_tone_curves[side][2][0x2ff] != 0 || img_tone_curves[side][2][0x3ff] != 0) {
        return 1;
    }
    if (side == 0) {
        if (img_tone_points_unset(0) != 0) return 0;
    } else {
        if (img_tone_points_unset(1) != 0) return 0;
    }
    return 1;
}

int img_tone_points_changed(int side)
{
    if (!win_params.flags.f.adf) {
        return 0;
    }
    if (side == 0) {
        if (util_mem_equal(&settings[0x109], img_tone_x_built, 0x12) && util_mem_equal(settings_tone_front_0, img_tone_front_built, 0x12)) return 0;
    } else {
        if (util_mem_equal(&settings[0x109], img_tone_x_built, 0x12) && util_mem_equal(settings_tone_back_0, img_tone_back_built, 0x12)) return 0;
    }
    return 1;
}

int img_tone_hook(int unused_arg)
{
    return 0;
}

void img_fit_tone_curve_ends(struct img_spline_point *in_points, int count, int side, int colour)
{
    int j;
    struct img_spline_point points[10];
    double slope, intercept;
    short value;
    if (count <= 4) return;
    points[0].x = in_points[0].x * 4;
    points[1].x = in_points[1].x * 4 + 3;
    points[count - 2].x = in_points[count - 2].x * 4 + 3;
    points[count - 1].x = in_points[count - 1].x * 4 + 3;
    if ((settings_byte_0x70[0] & 4) == 0) {
        points[0].y = in_points[0].y * 4;
        points[1].y = in_points[1].y * 4;
        points[count - 2].y = in_points[count - 2].y * 4;
        points[count - 1].y = in_points[count - 1].y * 4;
    } else {
        points[0].y = in_points[0].y;
        points[1].y = in_points[1].y;
        points[count - 2].y = in_points[count - 2].y;
        points[count - 1].y = in_points[count - 1].y;
    }
    slope = ((double)points[1].y - points[0].y) / ((double)points[1].x - points[0].x);
    intercept = (double)points[0].y - points[0].x * slope;
    for (j = 0; j <= points[1].x; j++) {
        value = j * slope + intercept;
        if (value > 127) value = 127;
        else if (value < -128) value = -128;
        img_tone_curves[side][colour][j] = value;
    }
    slope = ((double)points[count - 1].y - points[count - 2].y) / ((double)points[count - 1].x - points[count - 2].x);
    intercept = (double)points[count - 2].y - points[count - 2].x * slope;
    for (j = points[count - 2].x; j <= points[count - 1].x; j++) {
        value = j * slope + intercept;
        if (value > 127) value = 127;
        else if (value < -128) value = -128;
        img_tone_curves[side][colour][j] = value;
    }
}

extern void _builtin_set_imask(int);
extern int _builtin_get_imask(void);
extern unsigned short img_output_length_lines();


/* Image path set-up for one side: parameters, VDCC3 registers, halftone, gamma tables;
   returns an error code or 0. */
unsigned short img_setup_side(int side)
{
    unsigned short error;
    int pisces_enabled;
    int saved_imask;
    error = 0;
    saved_imask = _builtin_get_imask();
    error = img_compute_side_params(side, 0);
    if (error != 0) {
        return error;
    }
    if (hw_hostif_flags.f.own_hostif) {
        pisces_enabled = img_setup_pisces_if_enabled(side);
    } else {
        img_setup_pisces_emphasis(side);
        pisces_enabled = 0;
    }
    img_setup_vdcc(side);
    if (pisces_enabled != 0) {
        img_hook_setup(side);
    }
    error = img_prepare_halftone(side);
    if (error != 0) {
        return error;
    }
    error = img_prepare_gamma(side);
    if (error != 0) {
        return error;
    }
    img_load_vdcc_tables(side);
    img_load_halftone(side);
    _builtin_set_imask(15);
    img_mode_applied[side] = img_mode[side];
    _builtin_set_imask(saved_imask);
    return 0;
}

unsigned short img_compute_side_params(int side, int unused_arg)
{
    unsigned short error;
    error = 0;
    img_window = &win_params;
    img_decode_window_mode(side);
    error = img_select_resolutions(side);
    if (error != 0) {
        return error;
    }
    error = img_compute_geometry(side);
    if (error != 0) {
        return error;
    }
    return 0;
}

void img_compute_window_size(int side, int unused_arg, int width_out, int length_out)
{
    struct win_param_block *window;
    unsigned short saved_path_flags;
    int saved_imask;
    saved_imask = _builtin_get_imask();
    window = &win_params;
    _builtin_set_imask(15);
    saved_path_flags = img_mode[side].path_flags.v;
    img_mode[side].path_flags.v = 0;
    if (window->side[side].composition.f.color || window->side[side].composition.f.multi_level) {
        img_mode[side].path_flags.f.multi_level = 1;
    }
    if (window->side[side].compression.f.type & 0x80) {
        img_mode[side].path_flags.f.jpeg_output = 1;
        if (window->side[side].compression.f.type == SCSI_WIN_COMPRESSION_JPEG2) {
            img_mode[side].path_flags.f.jpeg2_output = 1;
        }
    }
    img_compute_width_px(side, window, (unsigned short *)width_out);
    img_output_length_lines(side, window, length_out);
    img_mode[side].path_flags.v = saved_path_flags;
    _builtin_set_imask(saved_imask);
}


void img_edge_state_1000_d_step_1(int side, short kernel_word)
{
    unsigned short width_px;
    unsigned short level;
    unsigned short long_page_level;
    unsigned short margin;
    if ((job_long_page_flags & 0x80) != 0 && win_white_level_follow != SCSI_WIN_WHITE_LEVEL_FOLLOW_OFF) {
        width_px = p_pisces_zoom[side]->width_px.v;
        p_pisces_kernel_ctrl[side]->reg_160 = 0;
        p_pisces_kernel_ctrl[side]->width_px = width_px;
        p_pisces_kernel_ctrl[side]->reg_164.b15 = 1;
        if (line_long_page_level_count != 0 && line_long_page_level_sum != 0) {
            level = rt_divu32(line_long_page_level_sum, line_long_page_level_count);
            if (level > 0xff) {
                level = 0xff;
            }
            if (level < 0x30) {
                level = 0x30;
            }
        } else {
            level = 0xc0;
        }
        if (job_sheet_count != 0 && img_long_page_level != 0) {
            long_page_level = img_long_page_level;
            margin = rt_divu16(long_page_level * 50 + 0x22b, 1000);
            if (long_page_level < margin) {
                long_page_level = margin;
            }
            if (level > long_page_level + margin || level < long_page_level - margin) {
                level = long_page_level;
            }
        }
        margin = rt_divu16(level * 94 + 0x22b, 1000);
        level = level - margin;
        p_pisces_kernel_ctrl[side]->reg_166.lo = level;
        if (job_sheet_count != 0) {
            p_pisces_kernel_ctrl[side]->reg_168.w = 0x1185;
            p_pisces_kernel_ctrl[side]->reg_16a = 0xff80;
            p_pisces_kernel[side]->w[0] = 0x1185;
            p_pisces_kernel[side]->w[1] = 0x8079;
            p_pisces_kernel[side]->w[14] = 1;
        }
        return;
    }
    if (img_white_level_follow_on(side) != 0) {
        width_px = p_pisces_zoom[side]->width_px.v;
        p_pisces_kernel_ctrl[side]->reg_160 = 0;
        p_pisces_kernel_ctrl[side]->width_px = width_px;
        p_pisces_kernel_ctrl[side]->reg_166.lo = 0xff;
        p_pisces_kernel_ctrl[side]->reg_164.b15 = 1;
        p_pisces_kernel_ctrl[side]->reg_168.f.lo = 5;
        if (width_px < 0x80) {
            p_pisces_kernel_ctrl[side]->reg_164.lo = 0;
        } else if (width_px < 0x100) {
            p_pisces_kernel_ctrl[side]->reg_164.lo = 1;
        } else if (width_px < 0x200) {
            p_pisces_kernel_ctrl[side]->reg_164.lo = 2;
        } else if (width_px < 0x400) {
            p_pisces_kernel_ctrl[side]->reg_164.lo = 3;
        } else if (width_px < 0x800) {
            p_pisces_kernel_ctrl[side]->reg_164.lo = 4;
        } else if (width_px < 0x1000) {
            p_pisces_kernel_ctrl[side]->reg_164.lo = 5;
        } else {
            p_pisces_kernel_ctrl[side]->reg_164.lo = 6;
        }
        p_pisces_kernel[side]->w[14] = kernel_word;
    } else {
        p_pisces_kernel_ctrl[side]->reg_160 = 0;
        p_pisces_kernel_ctrl[side]->width_px = 0;
        p_pisces_kernel_ctrl[side]->reg_166.lo = 0xff;
        p_pisces_kernel_ctrl[side]->reg_164.b15 = 0;
        p_pisces_kernel_ctrl[side]->reg_168.f.lo = 0;
    }
}

